/* ------------------------------------------------------------------ *
 * x-soori-library-section-header
 *
 * Standard components (instance-supplied, declared in innerComponents):
 *   - now-heading           : the title — colour, size and weight from the theme.
 *   - now-highlighted-value : the status label (e.g. "Broker Approved").
 * Owned markup — documented §5 exceptions (no design-system component fits):
 *   - .sh-subtitle    : plain muted inline note beside the title (e.g.
 *                       "Last refreshed 1m ago").
 *   - .sh-description : single muted paragraph beneath the title.
 * ------------------------------------------------------------------ */

/* statusColor (kept for compatibility) → now-highlighted-value colour. */
const STATUS_COLOR = { green: 'positive', amber: 'warning', red: 'critical', gray: 'gray' };

const view = (state) => {
	const {
		title,
		description,
		subtitle,
		status,
		statusColor,
		headingLevel,
		headingVariant,
		showDescription,
		showDivider,
	} = state.properties;

	return (
		<div className="sh-root">
			<div className="sh-title-row">
				<now-heading
					label={title || ''}
					level={Number(headingLevel) || 2}
					variant={headingVariant || 'header-secondary'}
					has-no-margin={true}
				></now-heading>
				{subtitle ? <span className="sh-subtitle">{subtitle}</span> : null}
				{status ? (
					<now-highlighted-value
						className="sh-status"
						label={status}
						color={STATUS_COLOR[statusColor] || STATUS_COLOR.green}
						variant="primary"
					/>
				) : null}
			</div>
			{showDescription && description ? (
				<p className="sh-description">{description}</p>
			) : null}
			{showDivider ? <hr className="sh-divider" aria-hidden="true" /> : null}
		</div>
	);
};

createCustomElement('x-soori-library-section-header', {
	renderer: { type: snabbdom },
	view,
	styles,
	properties: {
		title: { default: 'Selected Quote Option' },
		description: { default: 'The current selected quote option is below' },
		subtitle: { default: '' },
		status: { default: '' },
		statusColor: { default: 'green' },
		headingLevel: { default: '2' },
		headingVariant: { default: 'header-secondary' },
		showDescription: { default: true },
		showDivider: { default: false },
	},
});
